import std.io

pub type AppError = Failed(String)

record Cell { n: Int64 }

fn apply(f: fn(Int64) -> Int64, v: Int64) -> Int64 {
    return f(v)
}

pub fn main() effect io -> Result<(), AppError> {
    let c = Cell { n: 40 }
    let a = apply(|x| x + c.n, 2)
    let g: fn(Int64) -> Int64 = |x| x * 3
    let b = apply(g, 5)
    let h: fn(Int64) -> Int64 = |x| apply(g, x) + 1
    let d = h(2)
    io.println("${a}")
    io.println("${b}")
    io.println("${d}")
    return Ok(())
}
